9913	+import { useState } from "react";
9914	+import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
9915	+import { ApiError, api } from "../api/client";
9916	+import type { Assignment, MissionDetail } from "../api/types";
9917	+import { useAuth } from "../auth/AuthContext";
9918	+import { MissionStatusBadge } from "../components/StatusBadge";
9919	+import { ErrorBanner } from "../components/ErrorBanner";
9920	+import { Spinner } from "../components/Spinner";
9921	+import { FulfillmentBar } from "../components/FulfillmentBar";
9922	+import { formatDateRange, initials } from "../lib/format";
9923	+
9924	+function errorMessage(error: unknown, fallback: string): string {
9925	+  return error instanceof ApiError ? error.message : fallback;
9926	+}
9927	+
9928	+interface ProposeVars {
9929	+  requirementId: number;
9930	+  crewId: number;
9931	+}
9932	+
9933	+export function MissionDetailScreen({ missionId, onBack }: { missionId: number; onBack: () => void }) {
9934	+  const { user } = useAuth();
9935	+  const queryClient = useQueryClient();
9936	+  const [hasRunMatcher, setHasRunMatcher] = useState(false);
9937	+  const [showRejectForm, setShowRejectForm] = useState(false);
9938	+  const [rejectReason, setRejectReason] = useState("");
9939	+
9940	+  const missionQuery = useQuery({
9941	+    queryKey: ["mission", missionId],
9942	+    queryFn: () => api.mission.get(missionId),
9943	+  });
9944	+
9945	+  const assignmentsQuery = useQuery({
9946	+    queryKey: ["assignments"],
9947	+    queryFn: api.assignment.list,
9948	+  });
9949	+
9950	+  const matchQuery = useQuery({
9951	+    queryKey: ["match", missionId],
9952	+    queryFn: () => api.match.run(missionId),
9953	+    enabled: hasRunMatcher,
9954	+  });
9955	+
9956	+  const approveMutation = useMutation({
9957	+    mutationFn: () => api.mission.approve(missionId),
9958	+    onMutate: async () => {
9959	+      await queryClient.cancelQueries({ queryKey: ["mission", missionId] });
9960	+      const previous = queryClient.getQueryData<MissionDetail>(["mission", missionId]);
9961	+      if (previous) queryClient.setQueryData<MissionDetail>(["mission", missionId], { ...previous, status: "approved" });
9962	+      return { previous };
9963	+    },
9964	+    onError: (_err, _vars, context) => {
9965	+      if (context?.previous) queryClient.setQueryData(["mission", missionId], context.previous);
9966	+    },
9967	+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["mission", missionId] }),
9968	+  });
9969	+
9970	+  const rejectMutation = useMutation({
9971	+    mutationFn: (reason: string) => api.mission.reject(missionId, reason),
9972	+    onMutate: async (reason) => {
9973	+      await queryClient.cancelQueries({ queryKey: ["mission", missionId] });
9974	+      const previous = queryClient.getQueryData<MissionDetail>(["mission", missionId]);
9975	+      if (previous) queryClient.setQueryData<MissionDetail>(["mission", missionId], { ...previous, status: "draft" });
9976	+      return { previous, reason };
9977	+    },
9978	+    onSuccess: () => {
9979	+      setShowRejectForm(false);
9980	+      setRejectReason("");
9981	+    },
9982	+    onError: (_err, _vars, context) => {
9983	+      if (context?.previous) queryClient.setQueryData(["mission", missionId], context.previous);
9984	+    },
9985	+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["mission", missionId] }),
9986	+  });
9987	+
9988	+  const proposeMutation = useMutation({
9989	+    mutationFn: (vars: ProposeVars) => api.assignment.propose(missionId, vars.requirementId, vars.crewId),
9990	+    onMutate: async (vars) => {
9991	+      await queryClient.cancelQueries({ queryKey: ["assignments"] });
9992	+      const previous = queryClient.getQueryData<Assignment[]>(["assignments"]);
9993	+      const optimistic: Assignment = {
9994	+        // Negative id marks this row as "not yet confirmed by the server" —
9995	+        // the UI uses it to show the optimistic-update note (mockup: "shown
9996	+        // instantly on click"). Replaced by the real row once settled.
9997	+        id: -Date.now(),
9998	+        mission_id: missionId,
9999	+        requirement_id: vars.requirementId,
10000	+        crew_id: vars.crewId,
10001	+        proposed_by: user?.id ?? 0,
10002	+        status: "proposed",
10003	+        proposed_at: new Date().toISOString(),
10004	+        responded_at: null,
10005	+      };
10006	+      queryClient.setQueryData<Assignment[]>(["assignments"], (old) => [...(old ?? []), optimistic]);
10007	+      return { previous };
10008	+    },
10009	+    onError: (_err, _vars, context) => {
10010	+      if (context?.previous) queryClient.setQueryData(["assignments"], context.previous);
10011	+    },
10012	+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["assignments"] }),
10013	+  });
10014	+
10015	+  if (missionQuery.isPending) {
10016	+    return (
10017	+      <div className="flex flex-1 items-center justify-center px-10 py-8">
10018	+        <Spinner className="h-6 w-6 text-text-3" />
10019	+      </div>
10020	+    );
10021	+  }
10022	+
10023	+  if (missionQuery.isError) {
10024	+    return (
10025	+      <div className="flex flex-1 flex-col gap-4 px-10 py-8">
10026	+        <BackLink onBack={onBack} />
10027	+        <ErrorBanner message={errorMessage(missionQuery.error, "Couldn't load this mission.")} onRetry={() => missionQuery.refetch()} />
10028	+      </div>
10029	+    );
10030	+  }
10031	+
10032	+  const mission = missionQuery.data;
10033	+  const assignments = assignmentsQuery.data ?? [];
10034	+  const canReview = user?.role === "director" && mission.status === "pending_approval";
10035	+  const isOwnMission = mission.created_by === user?.id;
10036	+
10037	+  return (
10038	+    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-7">
10039	+      <BackLink onBack={onBack} />
10040	+
10041	+      <div>
