10043	+          <div className="text-2xl font-bold">{mission.name}</div>
10044	+          <MissionStatusBadge status={mission.status} />
10045	+        </div>
10046	+        <div className="mt-1.5 text-[13px] text-text-2">{formatDateRange(mission.start_date, mission.end_date)}</div>
10047	+        <p className="mt-2 max-w-2xl text-sm text-text-2">{mission.description}</p>
10048	+      </div>
10049	+
10050	+      <div className="flex items-start gap-7">
10051	+        {/* Left column */}
10052	+        <div className="flex min-w-0 flex-1 flex-col gap-5">
10053	+          <div className="rounded-[10px] border border-border bg-surface p-5">
10054	+            <div className="mb-4 text-[15px] font-bold">Requirements</div>
10055	+            {mission.requirements.length === 0 ? (
10056	+              <div className="text-sm text-text-3">No requirements added yet.</div>
10057	+            ) : (
10058	+              <div className="flex flex-col gap-3.5">
