10567	+
10568	+function errorMessage(error: unknown, fallback: string): string {
10569	+  return error instanceof ApiError ? error.message : fallback;
10570	+}
10571	+
10572	+// proposed needs a decision first, then confirmed, then declined history last.
10573	+const STATUS_ORDER: Record<AssignmentStatus, number> = { proposed: 0, confirmed: 1, declined: 2 };
10574	+
10575	+interface RespondVars {
10576	+  assignmentId: number;
10577	+  action: "accept" | "decline";
10578	+}
10579	+
10580	+export function MyAssignmentsScreen() {
10581	+  const queryClient = useQueryClient();
10582	+
10583	+  const assignmentsQuery = useQuery({ queryKey: ["assignments"], queryFn: api.assignment.list });
10584	+  const assignments = useMemo(
10585	+    () => [...(assignmentsQuery.data ?? [])].sort((a, b) => STATUS_ORDER[a.status] - STATUS_ORDER[b.status]),
10586	+    [assignmentsQuery.data],
10587	+  );
10588	+
10589	+  const missionIds = useMemo(() => Array.from(new Set(assignments.map((a) => a.mission_id))), [assignments]);
10590	+
10591	+  const missionQueries = useQueries({
10592	+    queries: missionIds.map((id) => ({
10593	+      queryKey: ["mission", id],
10594	+      queryFn: () => api.mission.get(id),
10595	+      enabled: assignmentsQuery.isSuccess,
10596	+    })),
10597	+  });
10598	+  const missionById = new Map<number, MissionDetail>();
10599	+  missionQueries.forEach((q, i) => {
10600	+    if (q.data) missionById.set(missionIds[i]!, q.data);
10601	+  });
10602	+  const missionsLoading = missionQueries.some((q) => q.isPending);
10603	+
10604	+  const respondMutation = useMutation({
10605	+    mutationFn: (vars: RespondVars) => api.assignment.respond(vars.assignmentId, vars.action),
10606	+    onMutate: async (vars) => {
10607	+      await queryClient.cancelQueries({ queryKey: ["assignments"] });
10608	+      const previous = queryClient.getQueryData<Assignment[]>(["assignments"]);
10609	+      queryClient.setQueryData<Assignment[]>(["assignments"], (old) =>
10610	+        (old ?? []).map((a) =>
10611	+          a.id === vars.assignmentId
10612	+            ? { ...a, status: vars.action === "accept" ? "confirmed" : "declined", responded_at: new Date().toISOString() }
10613	+            : a,
10614	+        ),
10615	+      );
10616	+      return { previous };
10617	+    },
10618	+    onError: (_err, _vars, context) => {
10619	+      if (context?.previous) queryClient.setQueryData(["assignments"], context.previous);
10620	+    },
10621	+    onSettled: () => queryClient.invalidateQueries({ queryKey: ["assignments"] }),
10622	+  });
10623	+
10624	+  return (
10625	+    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-8">
10626	+      <div>
10627	+        <div className="text-[22px] font-bold">My Assignments</div>
10628	+        <div className="mt-0.5 text-[13px] text-text-2">Missions you've been proposed or confirmed for.</div>
10629	+      </div>
10630	+
10631	+      {assignmentsQuery.isError && (
10632	+        <ErrorBanner
10633	+          message={errorMessage(assignmentsQuery.error, "Couldn't load your assignments.")}
10634	+          onRetry={() => assignmentsQuery.refetch()}
10635	+        />
10636	+      )}
10637	+
10638	+      {assignmentsQuery.isPending && (
10639	+        <div className="flex flex-col gap-3">
10640	+          {[0, 1, 2].map((i) => (
10641	+            <div key={i} className="h-20 animate-pulse rounded-[10px] border border-border bg-surface" />
10642	+          ))}
10643	+        </div>
10644	+      )}
10645	+
10646	+      {assignmentsQuery.isSuccess && assignments.length === 0 && (
10647	+        <div className="rounded-[10px] border border-border bg-surface px-5 py-10 text-center text-sm text-text-3">
10648	+          You haven't been proposed for any missions yet.
10649	+        </div>
10650	+      )}
10651	+
